mapper.select:
SELECT s.*, e.name as employee_name, e.employee_no as employee_no
FROM salary_record s
LEFT JOIN sys_employee e ON s.employee_id = e.id
WHERE s.deleted = 0

    AND s.employee_id = #{query.employeeId}


    AND s.month = #{query.month}


    AND s.status = #{query.status}

ORDER BY s.month DESC, s.create_time DESC
